// Private UI only; document mutations remain in the authority adapter.
export function contextualUI({document:d,frameDocument:f,registry,state,action,message}){
 const frame=d.querySelector('iframe'),panel=d.createElement('section');panel.className='conjure-popover';panel.hidden=true;panel.setAttribute('aria-label','Editor controls');d.querySelector('#conjure-shell').append(panel);
 let kind=null,restore=null,opener=null;
 const button=(label,fn,doc=f)=>{const b=doc.createElement('button');b.type='button';b.textContent=label;b.addEventListener('pointerdown',e=>e.stopPropagation());b.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();try{fn(b);}catch(error){message(error.message);}});return b;};
 function close(){if(state().pending){message('Apply or cancel pending settings first.');return;}restore?.();restore=null;panel.hidden=true;panel.replaceChildren();panel.onkeydown=null;kind=null;opener?.focus();}
 function open(type,trigger){close();if(!panel.hidden)return false;kind=type;opener=trigger;panel.hidden=false;panel.replaceChildren();panel.dataset.surface=type;return true;}
 function settings(type,trigger){if(!open(type+'-inspector',trigger))return;const selector=type==='section'?'[data-section-fields]':`[data-${type}-fields]`,fields=d.querySelector(selector);if(!fields){close();return;}const placeholder=d.createComment('settings home');fields.before(placeholder);fields.hidden=false;panel.append(fields);restore=()=>{placeholder.replaceWith(fields);};const dismiss=button('Done',close,d),cancel=button('Cancel changes',()=>{d.querySelector('[data-cancel-settings]').click();close();},d);panel.append(dismiss,cancel);panel.querySelector('input,select,button')?.focus();}
 function picker(trigger){if(!open('picker',trigger))return;const title=d.createElement('strong');title.textContent='Add Block';const search=d.createElement('input');search.type='search';search.placeholder='Search blocks';search.setAttribute('aria-label','Search blocks');const list=d.createElement('div');list.className='conjure-catalogue';list.setAttribute('role','group');list.setAttribute('aria-label','Essentials');const heading=d.createElement('p');heading.textContent='ESSENTIALS';
  const paint=()=>{list.replaceChildren();for(const def of registry.list().filter(x=>x.catalogue&&x.label.toLowerCase().includes(search.value.toLowerCase()))){const b=button(def.icon+' '+def.label,()=>{action('add',def.type);close();},d);b.dataset.blockType=def.type;list.append(b);}if(!list.children.length){const empty=d.createElement('p');empty.textContent='No supported blocks match.';list.append(empty);}};
  search.addEventListener('input',paint);panel.onkeydown=e=>{const cards=[...list.querySelectorAll('button')],i=cards.indexOf(d.activeElement);if(['ArrowDown','ArrowRight','ArrowUp','ArrowLeft'].includes(e.key)&&cards.length){e.preventDefault();cards[(i+(['ArrowUp','ArrowLeft'].includes(e.key)?cards.length-1:1)+cards.length)%cards.length].focus();}if(e.key==='Enter'&&e.target===search){e.preventDefault();cards[0]?.click();}};panel.append(title,search,heading,list,button('Close',close,d));paint();search.focus();}
 function layers(trigger){if(!open('layers',trigger))return;const title=d.createElement('strong');title.textContent='Layers';panel.append(title);for(const [index,s] of state().document.sections.entries()){const heading=button('Section '+(index+1),()=>{action('section',s.id);close();},d);panel.append(heading);for(const id of [...s.order].sort((a,b)=>s.layouts[state().bp].placements[b].value.z-s.layouts[state().bp].placements[a].value.z||s.order.indexOf(b)-s.order.indexOf(a))){const b=s.blocks[id],select=button((registry.get(b)?.label||b.type)+(s.layouts[state().bp].placements[id].value.locked?' · locked':''),()=>{action('select',id);close();},d);select.dataset.layerBlock=id;panel.append(select);}}panel.append(button('Close',close,d));panel.querySelector('button')?.focus();}
 function paint(){f.querySelectorAll('[data-conjure-controls]').forEach(e=>e.remove());const v=state();if(!v.editing)return;const selected=f.querySelector('[data-block][data-selected=true]'),section=f.querySelector(`[data-section="${v.sectionId}"]`);if(selected&&!v.pending){const b=v.document.sections.find(s=>s.blocks[v.selected])?.blocks[v.selected];if(b){const tools=f.createElement('div');tools.className='conjure-block-tools';tools.dataset.conjureControls='true';tools.setAttribute('role','toolbar');tools.setAttribute('aria-label',(registry.get(b)?.label||b.type)+' actions');const add=(label,fn)=>tools.append(button(label,fn));if(registry.can(b,'edit')){if(b.type==='text')add('Write',()=>action('write'));if(['image','button'].includes(b.type))add('Settings',trigger=>settings(b.type,trigger));}if(registry.can(b,'layer'))for(const [label,name] of [['Forward','forward'],['Backward','backward'],['Front','front'],['Back','back']])add(label,()=>action('stack',name));if(registry.get(b)?.duplicate)add('Duplicate',()=>action('duplicate'));if(registry.can(b,'remove'))add('Delete',()=>action('delete'));selected.append(tools);}}
  if(section&&!v.pending){const tools=f.createElement('div');tools.className='conjure-section-tools';tools.dataset.conjureControls='true';tools.setAttribute('role','toolbar');tools.setAttribute('aria-label','Section actions');for(const [label,fn] of [['+ Add Block',b=>picker(b)],['Section settings',b=>settings('section',b)],['Layers',b=>layers(b)]])tools.append(button(label,fn));section.append(tools);}
 }
 const escape=e=>{if(e.key==='Escape'&&!panel.hidden){e.preventDefault();close();}},clickAway=e=>{if(!panel.hidden&&!panel.contains(e.target)&&!e.target.closest?.('[data-advanced]'))close();};d.addEventListener('keydown',escape);f.addEventListener('keydown',escape);frame.addEventListener('load',close); // state sessions own cleanup
 return {paint,picker,layers,settings,close,get mode(){return kind;},destroy(){restore?.();panel.remove();d.removeEventListener('keydown',escape);f.removeEventListener('keydown',escape);frame.removeEventListener('load',close);}};
}
